import React, { useEffect } from 'react';
import styled from 'styled-components';
import { useGlobalContext } from '../../context/globalContext';
import { InnerLayout } from '../../styles/Layouts';
import Form from '../Form/Form';
import IncomeItem from '../IncomeItem/IncomeItem';

function Income() {
    const { incomes, getIncomes, deleteIncome, totalIncome } = useGlobalContext();

    useEffect(() => {
        getIncomes();
    }, []);

    return (
        <IncomeStyled>
            <InnerLayout>
                <div className="page-header">
                    <h1>💵 Income Tracker</h1>
                    <p>Manage and track all your income sources</p>
                </div>

                <div className="total-income-card">
                    <div className="card-content">
                        <span className="label">Total Income</span>
                        <p className="amount">₹{totalIncome()}</p>
                    </div>
                </div>

                <div className="income-content">
                    <div className="form-container">
                        <Form />
                    </div>

                    <div className="income-list">
                        <div className="list-header">
                            <h2>Your Incomes</h2>
                            <span className="count">{incomes.length} entries</span>
                        </div>
                        {incomes.length > 0 ? (
                            incomes.map((income) => {
                                const { _id, title, amount, date, category, description, type } = income;
                                return (
                                    <IncomeItem
                                        key={_id}
                                        id={_id}
                                        title={title}
                                        description={description}
                                        amount={amount}
                                        date={date}
                                        type={type}
                                        category={category}
                                        indicatorColor="var(--success-color)"
                                        deleteItem={deleteIncome}
                                    />
                                );
                            })
                        ) : (
                            <p className="no-incomes">No incomes recorded yet. Start by adding your first income! 📊</p>
                        )}
                    </div>
                </div>
            </InnerLayout>
        </IncomeStyled>
    );
}

const IncomeStyled = styled.div`
    display: flex;
    flex-direction: column;
    width: 100%;
    overflow: auto;
    background: var(--color-grey-lighter);

    .page-header {
        margin-bottom: 1.5rem;

        h1 {
            font-size: 2rem;
            font-weight: 700;
            color: var(--primary-color);
            margin: 0;
        }

        p {
            color: var(--color-grey);
            font-size: 0.95rem;
            margin: 0.5rem 0 0 0;
        }
    }

    .total-income-card {
        background: linear-gradient(135deg, var(--success-color), rgba(16, 185, 129, 0.6));
        border-radius: var(--radius-xl);
        padding: 2rem;
        margin-bottom: 2rem;
        box-shadow: var(--shadow-md);
        border: 1px solid rgba(16, 185, 129, 0.2);

        .card-content {
            display: flex;
            flex-direction: column;
            gap: 0.5rem;

            .label {
                color: rgba(255, 255, 255, 0.9);
                font-size: 0.9rem;
                font-weight: 500;
                text-transform: uppercase;
                letter-spacing: 0.5px;
            }

            .amount {
                font-size: 2.5rem;
                font-weight: 800;
                color: #fff;
                margin: 0;
            }
        }
    }

    .income-content {
        display: grid;
        grid-template-columns: 1fr 2fr;
        gap: 2rem;

        .form-container {
            display: flex;
            flex-direction: column;
            gap: 1.5rem;
        }

        .income-list {
            display: flex;
            flex-direction: column;
            gap: 1rem;

            .list-header {
                display: flex;
                justify-content: space-between;
                align-items: center;
                margin-bottom: 0.5rem;

                h2 {
                    font-size: 1.2rem;
                    font-weight: 600;
                    color: var(--primary-color);
                    margin: 0;
                }

                .count {
                    display: inline-flex;
                    align-items: center;
                    padding: 0.5rem 1rem;
                    background: rgba(16, 185, 129, 0.1);
                    border-radius: var(--radius-md);
                    color: var(--success-color);
                    font-size: 0.85rem;
                    font-weight: 600;
                }
            }

            .no-incomes {
                padding: 2rem;
                text-align: center;
                color: var(--color-grey);
                background: #fff;
                border-radius: var(--radius-lg);
                border: 2px dashed rgba(0, 0, 0, 0.1);
                font-style: italic;
            }
        }
    }

    @media (max-width: 1024px) {
        .income-content {
            grid-template-columns: 1fr;
        }
    }

    @media (max-width: 768px) {
        .page-header h1 {
            font-size: 1.5rem;
        }

        .total-income-card {
            padding: 1.5rem;

            .card-content .amount {
                font-size: 2rem;
            }
        }
    }
`;

export default Income;
